select mo.id, mo.order_no, mo.request_no, su.user_name, mo.user_id, mo.assigned_agent_id, mo.platform_code, mo.platform_name, mo.total_count, mo.success_count, mo.failed_count, mo.total_amount, mo.refund_amount, mo.order_status, mo.completed_time, mo.create_by, mo.create_time, mo.update_by, mo.update_time, mo.remark, ( select moi.phone from mark_order_item moi where moi.order_id = mo.id order by case when moi.process_status = '0' then 0 else 1 end, moi.id asc limit 1 ) as phone_preview from mark_order mo left join sys_user su on su.user_id = mo.user_id
and (mo.assigned_agent_id = #{agentId} or (mo.assigned_agent_id is null and su.create_by = #{agentUsername}))
and mo.order_no like concat('%', #{query.orderNo}, '%')
