and ( mo.order_no like concat('%', #{query.keyword}, '%') or su.user_name like concat('%', #{query.keyword}, '%') or exists ( select 1 from mark_order_item moi where moi.order_id = mo.id and moi.phone like concat('%', #{query.keyword}, '%') ) )
and mo.user_id = #{query.userId}
and mo.platform_code = #{query.platformCode}
and mo.order_status = #{query.orderStatus}
and mo.id in ( select moi.order_id from mark_order_item moi where moi.phone like concat('%', #{query.phone}, '%') )
and mo.create_time >= #{query.params.beginTime}
and mo.create_time <= concat(#{query.params.endTime}, ' 23:59:59')
order by mo.create_time desc

